head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.clickBzProcsNo = "";
scwin.vMode = "";
scwin.fn_GetPar, scwin.fn_SetPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.libRoundPanel.PanelToGroupBox(panel_Top);
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF71005.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF71005.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF71005.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF71005.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Excel_onclick = async function() {
    try {
        $c.stf.doLogSave("ULDSTF71005.xml", SCREN_PROCS_TP_CD_07);
        await scwin.excelDown();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF71005.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name btn_New_onclick
 * @description 「입력」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_New_onclick = async function() {
    try {
        await scwin.openChildForm("I");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF71005.btn_New_onclick" });
    }
};

/**
 * @method
 * @name img_IsuSearch_onclick
 * @description img_IsuSearch 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_IsuSearch_onclick = function() {
    try {
        scwin.fn_SetPar = scwin.setParIsur2;
        scwin.fn_GetPar = scwin.getParIsur2;
        $c.lcd.fn_PopFindDigitalIsurAppl();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF71005.img_IsuSearch_onclick" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onblur
 * @description txb_ISUR_CD 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onblur = function() {
    try {
        if (txb_ISUR_CD.getValue() === "") {
            txb_ISUR_NM.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF71005.txb_ISUR_CD_onblur" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF71005.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name grd_List_OnDblClick
 * @description grd_List 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_List_OnDblClick = async function(row, colid) {
    try {
        await scwin.openChildForm("U", row);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF71005.grd_List_OnDblClick" });
    }
};

/**
 * @method
 * @name txb_CHRG_NM_onkeyup
 * @description txb_CHRG_NM 키 입력 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txb_CHRG_NM_onkeyup = async function() {
    try {
        if (window.event.keyCode === 13) {
            await scwin.listSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF71005.txb_CHRG_NM_onkeyup" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    url += "?SCREN_ID=" + "ULDSTF71005.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=digitalEduCompltList&inputMessageId=DIGITAL_SUPPORT_EDU_SEARCH_OUT";
    url += "&BZ_PROCS_NO=";
    url += "&ISUR_CD=" + txb_ISUR_CD.getValue();
    url += "&CHRG_NM=" + txb_CHRG_NM.getValue();
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/digital/DigitalSupport.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setParIsur2
 * @description 상장신청인 선택 팝업호출용
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setParIsur2 = async function(arrPar) {
    const dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn === "Y") {
        txb_ISUR_CD.setValue(arrPar[0].ISUR_CD);
        txb_ISUR_NM.setValue(arrPar[0].ISUR_NM);
        await scwin.listSync();
    }
};

/**
 * @method
 * @name getParIsur2
 * @description get Par Isur2 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsur2 = function(arrPar) {
    arrPar[0] = "lds.stf.digital.select.isuracptlist.condition";
    return arrPar.length;
};

/**
 * @method
 * @name setBzProcsNo
 * @description set Bz Procs No 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setBzProcsNo = function(obj) {
    scwin.clickBzProcsNo = dts_List.getCellData(Number(obj), "BZ_PROCS_NO");
    // alert("fn_setBzProcsNo():"+clickBzProcsNo);

};

/**
 * @method
 * @name getBzProcsNo
 * @description get Bz Procs No 처리
 * @returns {void}
 * @hidden N
 */
scwin.getBzProcsNo = function() {
    return scwin.clickBzProcsNo;
};

/**
 * @method
 * @name openChildForm
 * @description open Child Form 처리
 * @param {*} mode mode
 * @param {Object} obj 컴포넌트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openChildForm = async function(mode, obj) {
    scwin.vMode = mode;
    if (scwin.vMode === "I") {
        scwin.clickBzProcsNo = "";
    } else {
        scwin.clickBzProcsNo = dts_List.getCellData(Number(obj), "BZ_PROCS_NO");
    }
    const options = {
        id: "ULDSTF71005_P",
        title: " 교육이수현황 입력",
        type: "browserPopup",
        width: "580px",
        height: "500px",
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/support/ULDSTF71005_P.gfm", options);
};

/**
 * @method
 * @name excelDown
 * @description 정보를 excel로 다운 받는다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.excelDown = async function() {
    if (dts_List.getRowCount() > 0) {
        $c.data.downloadGridViewExcel(grd_List, {fileName: "예비심사리스트", type: "3"});
    } else {
        await $c.win.alert("해당데이터가 없습니다. 조회후 다운받으십시요.");
    }
};

/**
 * @method
 * @name openDetail
 * @description open Detail 처리
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openDetail = async function(row) {
    let secugrpId;
    if (row > 0) {
        // 그리드에서 선택시
        scwin.setBzProcsNo(row);
        secugrpId = dts_List.getCellData(row, 'SECUGRP_ID');
    } else {
        // 신규버튼 선택시
        scwin.clickBzProcsNo = ""; // 초기화
        secugrpId = rdo_SECUGRP_ID.getValue();
    }
    const options = {
        id: "ULDSTF05401",
        title: $c.lcd.fn_getSecuGrpNm(secugrpId) + " 예비심사관리",
        type: "browserPopup",
        width: "560px",
        height: "470px",
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/lstproc/ULDSTF05401.gfm", options);
};
